    public static string Profile(CustomerAccountRecord customer, Store store)
    {
        var rows=store.Snapshot()["inquiries"]?.AsArray()??new JsonArray();
        var mine=rows.Where(x=>
        {
            try{var d=JsonNode.Parse(x?["data"]?.ToString()??"{}")?.AsObject();return string.Equals(d?["customerId"]?.ToString(),customer.Id,StringComparison.OrdinalIgnoreCase)||string.Equals(d?["email"]?.ToString(),customer.Email,StringComparison.OrdinalIgnoreCase);}catch{return false;}
        }).OrderByDescending(x=>x?["created"]?.ToString()).ToList();
        var list=new StringBuilder();
        foreach(var node in mine.Take(50))
        {
            var row=node!.AsObject(); JsonObject d; try{d=JsonNode.Parse(row["data"]?.ToString()??"{}")?.AsObject()??new JsonObject();}catch{d=new JsonObject();}
            var type=string.Equals(d["type"]?.ToString(),"service",StringComparison.OrdinalIgnoreCase)?"Servis":"Destek";
            var created=DateTimeOffset.TryParse(row["created"]?.ToString(),out var dt)?dt.ToLocalTime().ToString("dd.MM.yyyy HH:mm"):row["created"]?.ToString();
            var status=type=="Servis"?Status(d["serviceStatus"]?.ToString()??row["status"]?.ToString()):Status(row["status"]?.ToString());
            var summary=d["message"]?.ToString()??""; if(summary.Length>150)summary=summary[..150]+"…";
            list.Append($"<article class='request-card'><div><span class='type'>{E(type)}</span><strong>{E(row["requestCode"]?.ToString())}</strong></div><div class='request-main'><h3>{E(d["productName"]?.ToString()??(type+" talebi"))}</h3><p>{E(summary)}</p></div><div class='request-meta'><span>{E(status)}</span><time>{E(created)}</time></div></article>");
        }
        if(list.Length==0) list.Append("<div class='empty'><strong>Henüz talebiniz yok.</strong><span>Destek veya servis talebi oluşturduğunuzda burada görünecek.</span></div>");
        var html="""
