m;color:#19314d}textarea{min-height:88px;resize:vertical}input[readonly]{background:#f2f5f8;color:#6b7e91}.button{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;min-height:49px;padding:0 18px;border:1px solid #1459bd;border-radius:12px;background:linear-gradient(180deg,#287ce2,#1767d4);color:#fff;font:inherit;font-weight:850}.button:after{content:"";position:absolute;inset:-150% auto -150% -38%;width:34%;transform:rotate(20deg) translateX(-220%);background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),rgba(255,255,255,.95),rgba(255,255,255,.18),transparent);transition:transform .8s ease}.button:hover:after{transform:rotate(20deg) translateX(520%)}.note{min-height:22px;color:#1f6b4a;font-size:.84rem}.history-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:14px}.history-head a{color:#174c86;font-weight:800;text-decoration:none;font-size:.86rem}.requests{display:grid;gap:10px}.request-card{display:grid;grid-template-columns:145px minmax(0,1fr) 150px;gap:15px;align-items:center;padding:16px;border:1px solid #e0e8f1;border-radius:14px;background:#fff}.request-card>div:first-child{display:grid;gap:5px}.request-card .type{width:max-content;padding:4px 8px;border-radius:999px;background:#edf4ff;color:#174f8d;font-size:.7rem;font-weight:850}.request-card strong{font-size:.79rem;color:#536d88;overflow-wrap:anywhere}.request-main h3{margin:0 0 5px;font-size:1rem}.request-main p{margin:0;color:#677b91;font-size:.82rem;line-height:1.5}.request-meta{display:grid;justify-items:end;gap:5px}.request-meta span{font-size:.76rem;font-weight:850;color:#196548;background:#eaf6ef;padding:5px 8px;border-radius:999px}.request-meta time{font-size:.74rem;color:#708297}.quick{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.quick a{display:flex;align-items:center;justify-content:center;min-height:46px;border-radius:11px;background:#edf4ff;color:#164a82;text-decoration:none;font-weight:800;font-size:.84rem;border:1px solid #d6e4f7}.quick a:nth-child(2){background:#fff3e8;color:#b94f0c;border-color:#f0d2b7}.empty{display:grid;gap:4px;padding:30px;border:1px dashed #cad7e6;border-radius:14px;text-align:center;color:#61758e}.empty strong{color:#27445f}.security{margin-top:18px;padding-top:18px;border-top:1px solid #e3e9f0}.security a{color:#174c86;font-weight:800;text-decoration:none;font-size:.87rem}@media(max-width:900px){.layout{grid-template-columns:1fr}.welcome{align-items:flex-start;flex-direction:column}.request-card{grid-template-columns:130px minmax(0,1fr) 125px}}@media(max-width:600px){.top{padding:7px 10px}.top img{height:32px;max-width:150px}.top nav>a{display:none}.top button{min-height:38px}.wrap{width:calc(100% - 24px);margin:18px auto calc(34px + env(safe-area-inset-bottom))}.welcome{margin-bottom:14px}.welcome h1{font-size:2rem}.card{padding:18px 15px;border-radius:16px}.two{grid-template-columns:1fr}input,textarea,.button{min-height:52px;font-size:1rem}.quick{grid-template-columns:1fr}.request-card{grid-template-columns:1fr;gap:10px;padding:15px}.request-meta{justify-items:start;display:flex;align-items:center;justify-content:space-between}.request-main p{font-size:.86rem}.history-head{align-items:flex-start;flex-direction:column}.requests{gap:9px}}
