ebi oluştur</a><a href="/talep-sorgula">Telefonla talep durumu sorgula</a></div><div class="security"><a href="/account/security">Şifremi değiştir</a></div></section><section class="card"><div class="history-head"><div><h2>Talep geçmişim</h2></div><a href="/iletisim?amac=servis">Yeni teknik servis talebi</a></div><div class="requests">@@REQUESTS@@</div></section></div></main><script>document.getElementById('customer-profile').addEventListener('submit',async function(e){e.preventDefault();const f=e.currentTarget,n=document.getElementById('profile-note');n.textContent='Kaydediliyor…';const body=Object.fromEntries(new FormData(f).entries());try{const r=await fetch('/api/customer/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Profil kaydedilemedi.');n.textContent='Profil bilgileriniz güncellendi.';}catch(err){n.textContent=err.message||'Profil kaydedilemedi.';}});</script></body></html>
""";
        return html.Replace("@@NAME@@",E(customer.Name),StringComparison.Ordinal).Replace("@@EMAIL@@",E(customer.Email),StringComparison.Ordinal).Replace("@@PHONE@@",E(customer.Phone),StringComparison.Ordinal).Replace("@@BUSINESS@@",E(customer.BusinessName),StringComparison.Ordinal).Replace("@@ADDRESS@@",E(customer.Address),StringComparison.Ordinal).Replace("@@CITY@@",E(customer.City),StringComparison.Ordinal).Replace("@@DISTRICT@@",E(customer.District),StringComparison.Ordinal).Replace("@@TAXOFFICE@@",E(customer.TaxOffice),StringComparison.Ordinal).Replace("@@TAXNUMBER@@",E(customer.TaxNumber),StringComparison.Ordinal).Replace("@@REQUESTS@@",list.ToString(),StringComparison.Ordinal);
